"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["23107"],{74748(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.paginacao.cursor_invalido","status":400,"titulo":"Cursor inv\xe1lido"},"descricao":{"codigo":"uniplus.paginacao.cursor_invalido","requisitos":[],"oQueAconteceu":["Cada p\xe1gina de uma listagem traz um cursor que marca de onde a seguinte continua. Nas listagens que aceitam ordena\xe7\xe3o, filtro ou busca, essa marca \xe9 uma posi\xe7\xe3o **dentro de um conjunto j\xe1 recortado e ordenado**. O cursor recebido foi emitido pelo pr\xf3prio sistema e \xe9 \xedntegro, mas pertence a outra consulta: a ordena\xe7\xe3o (`sort`), um filtro (como a situa\xe7\xe3o, a concess\xe3o, o curso, a modalidade, o cadastro, o per\xedodo ou a op\xe7\xe3o de ver s\xf3 as pr\xf3prias decis\xf5es) ou o texto de busca (`q`, `busca`) mudou entre a p\xe1gina anterior e esta. Retomar de uma posi\xe7\xe3o que n\xe3o existe no novo conjunto faria a p\xe1gina pular ou repetir registros sem aviso, e por isso a continua\xe7\xe3o \xe9 recusada. A resposta traz o detalhe: \xabO cursor informado n\xe3o continua esta consulta. Refa\xe7a a listagem sem cursor.\xbb Nenhum item \xe9 devolvido.","Na vitrine de certames publicados a recusa tamb\xe9m acontece quando a cole\xe7\xe3o avan\xe7a no meio da navega\xe7\xe3o: se uma publica\xe7\xe3o ou retifica\xe7\xe3o feita depois da p\xe1gina anterior altera o recorte que est\xe1 sendo percorrido, o conjunto que o cursor marcava j\xe1 n\xe3o \xe9 o mesmo.","A ordem das recusas \xe9 fixa: primeiro v\xeam o tamanho de p\xe1gina e a dire\xe7\xe3o (veja [tamanho de p\xe1gina inv\xe1lido](/erros/uniplus.cursor.limit_invalido) e [dire\xe7\xe3o de pagina\xe7\xe3o inv\xe1lida](/erros/uniplus.cursor.direcao_invalida)); depois o cursor em si, que pode n\xe3o decodificar, ter expirado ou pertencer a outra listagem (veja [cursor de pagina\xe7\xe3o inv\xe1lido](/erros/uniplus.cursor.invalido) e [cursor de pagina\xe7\xe3o expirado](/erros/uniplus.cursor.expirado)); em seguida a forma e os campos aceitos da ordena\xe7\xe3o e dos filtros. S\xf3 ent\xe3o o cursor \xe9 conferido contra a consulta pedida, e \xe9 a\xed que esta causa aparece. A permiss\xe3o para listar, nas listagens que a exigem, \xe9 conferida antes de tudo isso.","Esta causa \xe9 distinta da de [cursor de pagina\xe7\xe3o inv\xe1lido](/erros/uniplus.cursor.invalido), que trata do cursor que n\xe3o decodifica ou que \xe9 de outra cole\xe7\xe3o. Aqui o cursor \xe9 da cole\xe7\xe3o certa, mas de outra consulta."],"comoResolver":["Refa\xe7a a listagem sem informar o cursor, com a ordena\xe7\xe3o, os filtros e a busca que deseja, e navegue pelas p\xe1ginas a partir dela. Quando mudar a ordena\xe7\xe3o, um filtro ou a busca, descarte o cursor da navega\xe7\xe3o anterior: ele vale s\xf3 para a consulta que o emitiu. N\xe3o monte nem edite o cursor \xe0 m\xe3o; use sempre o valor devolvido no cabe\xe7alho `Link` da resposta, com os mesmos par\xe2metros da consulta que o gerou."],"ondeAparece":["Listagem de cursos","Listagem de ofertas de curso","Listagem da fila de provid\xeancias de acesso","Listagem das decis\xf5es da prote\xe7\xe3o de dados do cat\xe1logo","Listagem da vitrine de certames publicados"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Paginacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);